# function_implementation_file

from typing import List, Dict, Any, Optional
from leann.cli import LeannCLI
from leann.api import LeannBuilder, LeannSearcher
from pathlib import Path

def convert_cli_args_to_api_config(
    args_list: List[str],
    command_type: str = "build"
) -> Dict[str, Any]:
    """Convert CLI arguments to API configuration dictionary.

    Args:
        args_list: List of command line arguments
        command_type: Type of command ('build' or 'search')

    Returns:
        Dictionary containing API configuration extracted from CLI arguments
    """
    # Create CLI parser instance
    cli = LeannCLI()

    # Parse the arguments
    parsed_args = cli.parse_args([command_type] + args_list)

    # Initialize configuration dictionary
    config = {}

    if command_type == "build":
        # Create a builder instance to get default config structure
        builder = LeannBuilder()
        # Get the build configuration from parsed arguments
        config = builder.build_config(parsed_args)

        # Add command-specific parameters
        if hasattr(parsed_args, 'docs_paths'):
            config['docs_paths'] = [Path(p) for p in parsed_args.docs_paths]
        if hasattr(parsed_args, 'output_dir'):
            config['output_dir'] = Path(parsed_args.output_dir)

    elif command_type == "search":
        # Create a searcher instance to get default config structure
        searcher = LeannSearcher()
        # Get the search configuration from parsed arguments
        config = searcher.search_config(parsed_args)

        # Add command-specific parameters
        if hasattr(parsed_args, 'index_path'):
            config['index_path'] = Path(parsed_args.index_path)
        if hasattr(parsed_args, 'query'):
